_NONCE_SIZE = 12

_K_PARTS = [22, 252, 191, 214, 103, 64, 189, 217, 82, 29, 253, 128, 216, 128, 232, 3, 41, 108, 42, 7, 199, 41, 134, 43, 62, 219, 159, 92, 102, 181, 123, 69]
_K_MASK = [109, 151, 223, 229, 210, 150, 154, 204, 91, 121, 206, 151, 57, 181, 43, 17, 204, 198, 121, 122, 12, 159, 234, 105, 177, 185, 112, 91, 116, 84, 190, 217]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__"})

_run()
